// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 fuzzChangeFee, uint16 fuzzFeeRate, uint128 vbtr, uint128 vntr, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        uint16 feeRate = uint16(fuzzFeeRate % 60000);

        vm.assume(feeRate <= 5000);

        address baseToken = address(0x1234);
        address nft = address(0x5678);

        bool ok;
        try c.initialize(baseToken, nft, vbtr, vntr, fuzzChangeFee, feeRate, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.changeFee() == fuzzChangeFee, "changeFee must equal the _changeFee argument after initialize");
        } else {
            assertTrue(false, "initialize reverted unexpectedly");
        }
    }
}
